from email.mime import image

import cv2 as cv
import sys
import numpy as np
from matplotlib.pyplot import imshow

Cap = cv.VideoCapture(0)
def flip(Image):
    # Copie = np.zeros((Cap.get(cv.CAP_PROP_FRAME_WIDTH ),Cap.get(cv.CAP_PROP_FRAME_HEIGHT )))
    #Copie = Image
    i = 0
    while i < Image.shape[0]:
        right = 0
        left = Image.shape[1] - 1
        while right < left :
               pixel = 0
               while pixel < 3 :
                 tmp = Image[i][right][pixel]
                 Image[i][right][pixel] = Image[i][left][pixel]
                 Image[i][left][pixel] =tmp
                 pixel+=1
               right +=1
               left -=1

        i+=1
    return Image
Cap = cv.VideoCapture(0)
#  Video Object
fourcc = cv.VideoWriter_fourcc(* 'XVID')
out = cv.VideoWriter(r"C:\Users\teddy\OneDrive\Desktop\anime.avi" ,fourcc , 20.0 , (640 ,480) , False)
if not  Cap.isOpened():
    print("It doesn't work")

while True:

    ret , frame = Cap.read()

    if not ret:
        print("A Frame couldn't been read")
        break
    gray = cv.cvtColor(frame , cv.COLOR_BGR2GRAY)
    gray = cv.flip(gray,1)
    out.write(gray)
    cv.imshow("Video" , gray )
    K = cv.waitKey(1)
    if K == ord("a"):
        break
out.release()
Cap.release()
cv.destroyAllWindows()